// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }

    // General rule: for any caller that hasn't been blacklisted yet, after a
    // successful `getTokens()` call the caller's balance must be >= its pre-call
    // balance. The reference always credits the caller (or leaves the balance
    // unchanged when value is already zero); the mutant subtracts value, so for
    // any non-zero value the post-call balance is strictly less.
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        // Owner (deployer) is the only address that starts non-zero; the fuzzer
        // should not target the owner so that we exercise distr on a fresh account.
        vm.assume(caller != address(this));
        // Fresh addresses are not blacklisted; skip any address that already is.
        assumeNotBlacklisted(caller);

        uint256 pre = c.balanceOf(caller);
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.getTokens{value: 1 ether}();
        uint256 post = c.balanceOf(caller);

        assertTrue(post >= pre);
    }

    function assumeNotBlacklisted(address a) internal view {
        require(!c.blacklist(a), "blacklisted");
    }
}
